script:
(function () {
  'use strict';
  // Dividend reinvestment breakeven after a price drop. Monthly simulation for up to 50 years:
  //   price grows by (1 + g)^(1/12) − 1 a month; annual dividend per share starts at
  //   today's price × yield and grows by (1 + dividend growth)^(m/12); each payment is 1/frequency of it.
  //   Reinvesting: dividend ÷ price buys more shares. Cash: dividends pile up as cash (no interest).
  //   Breakeven = first month the position (plus cash, if taken) is worth at least the total invested.
  // Checks (scratchpad tests/dividend-reinvestment.test.js): price only, 20% drop at 5%/yr =
  //   55 months (closed form ln(1.25)/ln(1.05) = 4.57 yrs, rounded up to a whole month);
  //   0% price growth, 4% yield paid quarterly, 0% dividend growth: reinvesting = 23 quarters = 69 months
  //   (ln(1.25)/ln(1.01) = 22.4), cash = 75 months (0.8% of cost a quarter to cover 20%).
  // Fixes vs the old site: extra monthly investments were counted as recovered value (now they are
  // added to the cost); the breakeven figure was one month short and dividends were paid one month
  // late; milestones below the starting value showed "not reached".
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var shareFmt = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 });
  var MAX_MONTHS = 600;

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function duration(m) {
    if (m === null) return 'Over 50 years';
    if (m === 0) return 'Already even';
    var y = Math.floor(m / 12), mo = m % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' yr' : ' yrs'));
    if (mo) parts.push(mo + (mo === 1 ? ' mo' : ' mos'));
    return parts.join(' ');
  }

  function simulate(o) {
    var gm = Math.pow(1 + o.growth, 1 / 12) - 1;
    var price = o.cost * (1 - o.drop), dps0 = price * o.yieldRate, every = 12 / o.freq;
    var invested = o.cost * o.shares;
    var drip = o.shares, cashShares = o.shares, cash = 0, plain = o.shares;
    var be = { drip: null, cash: null, price: null }, beShares = 0, bePrice = 0, rows = [], yearDivs = 0;
    if (drip * price >= invested) { be.drip = be.cash = be.price = 0; beShares = drip; bePrice = price; }
    for (var m = 1; m <= MAX_MONTHS && (be.drip === null || be.cash === null || be.price === null || m <= 12 * Math.ceil(be.drip / 12)); m++) {
      price *= 1 + gm;
      if (m % every === 0) {
        var perShare = dps0 * Math.pow(1 + o.divGrowth, m / 12) / o.freq;
        var div = drip * perShare;
        yearDivs += div;
        drip += div / price;
        cash += cashShares * perShare;
      }
      if (o.monthly > 0) {
        var add = o.monthly / price;
        drip += add; cashShares += add; plain += add; invested += o.monthly;
      }
      if (be.drip === null && drip * price >= invested) { be.drip = m; beShares = drip; bePrice = price; }
      if (be.cash === null && cashShares * price + cash >= invested) be.cash = m;
      if (be.price === null && plain * price >= invested) be.price = m;
      if (m % 12 === 0 && (be.drip === null || m <= 12 * Math.ceil(be.drip / 12))) {
        rows.push({ year: m / 12, price: price, shares: drip, divs: yearDivs, value: drip * price, share: drip * price / invested });
      }
      if (m % 12 === 0) yearDivs = 0;
    }
    return { be: be, beShares: beShares, bePrice: bePrice, rows: rows };
  }

  function update() {
    var o = {
      cost: num('drCost'), shares: num('drShares'), drop: num('drDrop') / 100, growth: num('drGrowth') / 100,
      yieldRate: num('drYield') / 100, divGrowth: num('drDivGrowth') / 100, monthly: num('drMonthly'),
      freq: parseInt(document.getElementById('drFreq').value, 10)
    };
    var error = document.getElementById('drError');
    var msg = '';
    if ([o.cost, o.shares, o.drop, o.growth, o.yieldRate, o.divGrowth, o.monthly].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.cost <= 0 || o.shares <= 0) msg = 'Enter a share price and number of shares greater than 0.';
    else if (o.drop < 0 || o.drop > 0.95) msg = 'Enter a price decline from 0% to 95%.';
    else if (o.growth < -0.5 || o.growth > 1) msg = 'Enter share price growth from -50% to 100% a year.';
    else if (o.yieldRate < 0 || o.yieldRate > 0.3) msg = 'Enter a dividend yield from 0% to 30%.';
    else if (o.divGrowth < -0.5 || o.divGrowth > 0.5) msg = 'Enter dividend growth from -50% to 50% a year.';
    else if (o.monthly < 0) msg = 'The extra monthly investment cannot be negative.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var now = o.cost * (1 - o.drop), r = simulate(o);
    document.getElementById('drNowPrice').textContent = money.format(now);
    document.getElementById('drDrip').textContent = duration(r.be.drip);
    document.getElementById('drCash').textContent = duration(r.be.cash);
    document.getElementById('drPrice').textContent = duration(r.be.price);
    document.getElementById('drInvested').textContent = money.format(o.cost * o.shares);
    document.getElementById('drValueNow').textContent = money.format(now * o.shares);
    document.getElementById('drLoss').textContent = money.format((o.cost - now) * o.shares);
    var reached = r.be.drip !== null;
    document.getElementById('drSharesBe').textContent = reached ? shareFmt.format(r.beShares) : '–';
    document.getElementById('drPriceBe').textContent = reached ? money.format(r.bePrice) : '–';
    var dateText = '–';
    if (reached && r.be.drip === 0) dateText = 'Now';
    else if (reached) {
      var d = new Date();
      d.setDate(1);
      d.setMonth(d.getMonth() + r.be.drip);
      dateText = d.toLocaleDateString('en-US', { year: 'numeric', month: 'long' });
    }
    document.getElementById('drDate').textContent = dateText;
    document.getElementById('drSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.price) + '</td><td>' + shareFmt.format(row.shares) + '</td><td>' +
             money.format(row.divs) + '</td><td>' + money.format(row.value) + '</td><td>' + (row.share * 100).toFixed(1) + '%</td></tr>';
    }).join('') || '<tr><td colspan="6">The position is already worth what you paid.</td></tr>';
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('drForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
